{
  "returncode": 0,
  "output": "
        & > form:not(:has(.card__column-name--current)) + form:not(:has(.card__column-name--current)) {
          box-shadow: -1px 0 0 0 var(--color-container);
        }
      }
    }

    .card__column-name {
      @media (max-width: 639px) {
        justify-content: center;
      }
    }

    .card__closed {
      @media (max-width: 639px) {
        inset: auto 0 3rem auto;
        scale: 75%;
      }
    }

    .card__footer {
      --btn-size: 2.5rem;

      display: flex;
      gap: 0.5ch;
      inline-size: 100%;
      text-align: start;

      /* Switch to grid layout so that the bg zoom button can stay next to the
       * meta element, and the reactions can sit below */
      &:has(.reaction) {
        display: grid;
        grid-template-columns: 1fr auto;
        grid-template-areas:
          "meta bg-zoom"
          "reactions reactions";
      }

      @media (max-width: 639px) {
        display: grid;
        font-size: var(--text-x-small);
        gap: 1ch 0;
        grid-template-columns: 1fr auto;
        grid-template-areas:
          "meta bg-zoom"
          "meta reactions";

        &:not(:has(.reaction)),
        &:has(.card__background) {
          column-gap: 2ch;
        }
      }
    }

