import { Controller } from "@hotwired/stimulus"
import { nextFrame } from "helpers/timing_helpers"

// Turns the "add a reaction" button into a small form, and reveals the way to
// remove one of your own reactions.
export default class extends Controller {
  static targets = [ "trigger", "form", "input", "menu" ]

  open() {
    this.triggerTarget.hidden = true
    this.formTarget.hidden = false
    this.formTarget.classList.add("expanded")

    this.focusInput()
  }

  close() {
    this.formTarget.hidden = true
    this.formTarget.classList.remove("expanded")
    this.menuTarget?.removeAttribute("open")
    this.formTarget.querySelector("form")?.reset()
    this.triggerTarget.hidden = false
  }

  submitEnd(event) {
    if (event.detail.success) this.close()
  }

  toggleExpanded(event) {
    if (event.target.closest("form")) return

    event.currentTarget.classList.toggle("expanded")
  }

  remove(event) {
    event.currentTarget.closest(".reaction")?.classList.add("reaction--deleting")
  }

  focusInput() {
    if (this.menuTarget?.open) return

    nextFrame().then(() => this.inputTarget.focus())
  }

  closeMenu(event) {
    if (!this.menuTarget.open || this.menuTarget.contains(event.target)) return

    this.menuTarget.removeAttribute("open")
  }

  pick(event) {
    this.inputTarget.value = event.currentTarget.textContent.trim()
    this.inputTarget.dispatchEvent(new Event("input", { bubbles: true }))
    this.menuTarget.removeAttribute("open")
    this.inputTarget.focus()
  }
}
EOF
